sys_variable_value.value:
// Pass or fail a step: Override the step outcome to pass or fail.
//
//  - Return true from the main function body to pass the step
//  - Return false from the main function body to fail the step
//
//
// outputs:       Pre-defined Step config Output variables to set on this step during 
//                execution that are available to later steps
//
// steps(SYS_ID): A function to retrieve Output variable data from a step that executed
//                earlier in the test. The desired step's sys_id is required
//
// params:        The current test run data set's parameter data including both 
//                exclusive and shared parameters
//
//  Example:
//
//      // Test step 1 - add data
//      var gr = new GlideRecord('sc_task');
//      // If parameterized testing is enabled, parameters are stored in the params object
//      gr.setValue('short_description', params.u_my_short_description)
//      gr.setValue('caller', params.u_my_user.manager)
//      // this sample step's Step config has Output variables named table and record_id
//      outputs.table = 'sc_task';
//      outputs.record_id = gr.insert();
//
//      // Test step 2 - access added data and validate
//      // check that the record exists (or that business logic changed it)
//      var gr = new GlideRecord("sc_task");
//      gr.get(steps(PREVIOUS_STEP_SYS_ID).record_id);
//      assertEqual({name: "task gr exists", shouldbe: true, value: gr.isValidRecord()});
//
//
// stepResult.setOutputMessage: Log a message to step results after step executes.
//                              Can only be called once or will overwrite previous 
//                              message
//
//  Example:
//
//      var gr = new GlideRecord('sc_task');
//      gr.setValue('short_description', 'verify task can be inserted');
//      var grSysId = gr.insert();
//      var justCreatedGR = new GlideRecord('sc_task');
//      if (justCreatedGR.get(grSysId)) {
//            stepResult.setOutputMessage("Successfully inserted task record");
//            return true; // pass the step
//      } else { 
//            stepResult.setOutputMessage("Failed to insert task record");
//            return false; // fail the step
//      }
//
//
// assertEqual: A function used to compare that assertion.shouldbe == assertion.value;
//              in case of failure it throws an Error and logs that the assertion by
//              name has failed
//
//  Example:
//
//      var testAssertion = {
//            name: "my test assertion",
//            shouldbe: "expected value"
//            value: "actual value",
//      };
//      assertEqual(testAssertion); // throws Error, logs message to test step output
//
/* global x_hccc_hoc_ohs */
(
    function(outputs, steps, params, stepResult, assertEqual) {
        //init variables
        var result = true;
        var telwrkUtils = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();
        var insertRecordStep = steps('3508fdba3b019a18aeb1ebc964e45a2c'); //insert record
        var outputMessage = '';
        var teleworkAgreement = new GlideRecord('x_hccc_hoc_ohs_telework_agreement')
        teleworkAgreement.get(insertRecordStep.record_id);

        //Fixing the UTC dates
        if (params.u_telework_start_date) {
            teleworkAgreement.telework_start_date = params.u_telework_start_date;
        }
        if (params.u_telework_end_date) {
            teleworkAgreement.telework_end_date = params.u_telework_end_date;
        }
        if (params.u_approval_set) {
            //teleworkAgreement.approval_set = params.u_approval_set; //+10h
            //teleworkAgreement.approval_set = params.u_approval_set.getValue(); //+10h
            //teleworkAgreement.approval_set = params.u_approval_set.getDisplayValue(); //+5h
            //teleworkAgreement.approval_set.setDisplayValue(params.u_approval_set.getDisplayValue()); //+5h
            //teleworkAgreement.approval_set.setDisplayValue(params.u_approval_set.getValue()); //+5h
            //teleworkAgreement.approval_set.setDisplayValue(params.u_approval_set); //+10h
            //teleworkAgreement.approval_set.setValue(params.u_approval_set); //+5h
            teleworkAgreement.approval_set.setValue(params.u_approval_set.getDisplayValue()); //0h
        }
        teleworkAgreement.update();


        //helper functions
        function getEmployeeNumber(teleworkAgreementGr) {
            var employeeNumber = telwrkUtils._getEmployeeNumber(teleworkAgreementGr.subject_person);
            return employeeNumber;
        }

        function getUnit4Object(teleworkAgreementGr) {
            var unit4Obj = telwrkUtils._getUnit4Obj(teleworkAgreementGr);

            return unit4Obj;
        }

        function sendToUnit4(employeeNumber, teleworkAgreementString) {
            var actionResult = telwrkUtils._sendWithFlowAction(employeeNumber, teleworkAgreementString);
            return actionResult;
        }

        function assert(name, value, shouldbe) {
            var testAssertion = {
                name: name,
                shouldbe: shouldbe,
                value: value
            };

            assertEqual(testAssertion);
        }

        function compareObj(unit4Obj, expectedObj) {
            var res = true;

            assert("telework_number_fx", unit4Obj.telework_number_fx, expectedObj.telework_number_fx);
            assert("type_of_telework_fx", unit4Obj.type_of_telework_fx, expectedObj.type_of_telework_fx);
            assert("number_of_days_fx", unit4Obj.number_of_days_fx, expectedObj.number_of_days_fx);
            assert("telework_monday_fx", unit4Obj.telework_monday_fx, expectedObj.telework_monday_fx);
            assert("telework_tuesday_fx", unit4Obj.telework_tuesday_fx, expectedObj.telework_tuesday_fx);
            assert("telework_wednesday_fx", unit4Obj.telework_wednesday_fx, expectedObj.telework_wednesday_fx);
            assert("telework_thursday_fx", unit4Obj.telework_thursday_fx, expectedObj.telework_thursday_fx);
            assert("telework_friday_fx", unit4Obj.telework_friday_fx, expectedObj.telework_friday_fx);
            assert("telework_start_date_fx", unit4Obj.telework_start_date_fx, expectedObj.telework_start_date_fx);
            assert("telework_end_date_fx", unit4Obj.telework_end_date_fx, expectedObj.telework_end_date_fx);
            assert(
                "telework_location_addr_fx",
                unit4Obj.telework_location_addr_fx,
                expectedObj.telework_location_addr_fx
            );
            assert(
                "telework_telephone_num_fx",
                unit4Obj.telework_telephone_num_fx,
                expectedObj.telework_telephone_num_fx
            );
            assert(
                "emergency_contact_name_fx",
                unit4Obj.emergency_contact_name_fx,
                expectedObj.emergency_contact_name_fx
            );
            assert(
                "emergency_tel_number_fx",
                unit4Obj.emergency_tel_number_fx,
                expectedObj.emergency_tel_number_fx
            );
            assert(
                "relationship_to_employ_fx", unit4Obj.relationship_to_employ_fx, expectedObj.relationship_to_employ_fx);
            //assert("approver_name_fx", unit4Obj.approver_name_fx, expectedObj.approver_name_fx);
            assert("approved_date_fx", unit4Obj.approved_date_fx, expectedObj.approved_date_fx);

            return res;
        }

        //actual test
        //init
        var employeeNumber = getEmployeeNumber(teleworkAgreement);
        var unit4Obj = getUnit4Object(teleworkAgreement);
        if (params.u_closed_by_override) { //TODO this doesn't seem to go in for dataset 3
            unit4Obj.approver_name_fx = params.u_closed_by_override + '';
        }
        var expectedObj = JSON.parse(params.u_expected_object_sent);
        expectedObj.telework_number_fx = teleworkAgreement.getValue('number'); //can't add teleworkNumber to the params since it changes

        var teleworkAgreementString = JSON.stringify(unit4Obj);

        //outputMessage += '\r\nAgreement number: ' + teleworkAgreement.number.toString();
        //outputMessage += '\r\nparams.u_expected_object_sent: ' + JSON.stringify(expectedObj);
        outputMessage += '\r\n\r\nagreementString: ' + teleworkAgreementString;
        stepResult.setOutputMessage(outputMessage);

        compareObj(unit4Obj, expectedObj);

        if (params.u_should_try_to_upload) {
            outputMessage += '\r\nTrying record upload to unit4, it should ' +
                (params.u_should_upload ? 'succeed' : 'fail');
            result = sendToUnit4(employeeNumber, teleworkAgreementString);
            outputMessage += '\r\nDid it send to Unit4 Correctly: ' + !!result;
            assert('Should Upload', result, params.u_should_upload);
        } else {
            outputMessage += '\r\nSkipping record upload to unit4';
        }

        stepResult.setOutputMessage(outputMessage);
        //return result;
    }
)(outputs, steps, params, stepResult, assertEqual);
